// Generated by AI
#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

/// <summary>
/// Editor tool that builds a simple S.U.C.K.-3000 prop (backpack, hose and funnel)
/// from Unity primitives, attaches it to the player and assigns the Nozzle of the
/// VacuumAbsorber. Select PlayerArmature, then use Tools > S.U.C.K.-3000 > Build Vacuum Prop.
/// This file must be inside a folder named "Editor".
/// </summary>
public static class VacuumPropBuilder
{
    private const string PropName = "SUCK3000_Prop";
    private const string MaterialFolder = "Assets/GameMaterials";

    [MenuItem("Tools/S.U.C.K.-3000/Build Vacuum Prop")]
    public static void Build()
    {
        GameObject selected = Selection.activeGameObject;
        VacuumAbsorber absorber = selected != null ? selected.GetComponentInParent<VacuumAbsorber>() : null;

        if (absorber == null)
        {
            EditorUtility.DisplayDialog(
                "S.U.C.K.-3000",
                "Select PlayerArmature first (the object that has the Vacuum Absorber component).",
                "OK");
            return;
        }

        Transform parent = absorber.transform.Find("Geometry");
        if (parent == null)
        {
            parent = absorber.transform;
        }

        // Rebuilding replaces the previous prop.
        Transform old = parent.Find(PropName);
        if (old != null)
        {
            Undo.DestroyObjectImmediate(old.gameObject);
        }

        Material darkMetal = GetMaterial("SUCK_DarkMetal", new Color(0.18f, 0.19f, 0.21f), 0.8f, 0.55f, false);
        Material teal = GetMaterial("SUCK_Teal", new Color(0.1f, 0.75f, 0.65f), 0.3f, 0.6f, false);
        Material glow = GetMaterial("SUCK_Light", new Color(0.2f, 0.9f, 1f), 0f, 0.5f, true);

        GameObject root = new GameObject(PropName);
        Undo.RegisterCreatedObjectUndo(root, "Build vacuum prop");
        root.transform.SetParent(parent, false);

        // Backpack (positions are local to Geometry: +Z is the direction Alex faces).
        CreatePart(root.transform, "Backpack_Body", PrimitiveType.Cube,
            new Vector3(0f, 1.3f, -0.28f), Quaternion.identity, new Vector3(0.42f, 0.6f, 0.22f), darkMetal);
        CreatePart(root.transform, "Tank_Left", PrimitiveType.Cylinder,
            new Vector3(-0.3f, 1.25f, -0.28f), Quaternion.identity, new Vector3(0.16f, 0.3f, 0.16f), teal);
        CreatePart(root.transform, "Tank_Right", PrimitiveType.Cylinder,
            new Vector3(0.3f, 1.25f, -0.28f), Quaternion.identity, new Vector3(0.16f, 0.3f, 0.16f), teal);
        CreatePart(root.transform, "Status_Light", PrimitiveType.Sphere,
            new Vector3(0f, 1.5f, -0.4f), Quaternion.identity, new Vector3(0.09f, 0.09f, 0.09f), glow);

        // Hose: goes from the backpack over the right shoulder to the front.
        Vector3[] hosePath =
        {
            new Vector3(0.22f, 1.45f, -0.3f),
            new Vector3(0.38f, 1.6f, -0.05f),
            new Vector3(0.4f, 1.15f, 0.35f),
            new Vector3(0.3f, 1.0f, 0.6f)
        };

        for (int i = 0; i < hosePath.Length - 1; i++)
        {
            CreateTube(root.transform, "Hose_" + i, hosePath[i], hosePath[i + 1], 0.04f, darkMetal);
        }

        for (int i = 0; i < hosePath.Length; i++)
        {
            CreatePart(root.transform, "Hose_Joint_" + i, PrimitiveType.Sphere,
                hosePath[i], Quaternion.identity, new Vector3(0.09f, 0.09f, 0.09f), darkMetal);
        }

        // Funnel (the mouth of the vacuum), pointing forward.
        Quaternion pointForward = Quaternion.Euler(90f, 0f, 0f);
        CreatePart(root.transform, "Funnel", PrimitiveType.Cylinder,
            new Vector3(0.3f, 1.0f, 0.7f), pointForward, new Vector3(0.32f, 0.09f, 0.32f), teal);
        CreatePart(root.transform, "Funnel_Inside", PrimitiveType.Cylinder,
            new Vector3(0.3f, 1.0f, 0.795f), pointForward, new Vector3(0.24f, 0.01f, 0.24f), darkMetal);

        // Nozzle: the point where the absorbed waste flies to.
        GameObject nozzle = new GameObject("Nozzle");
        nozzle.transform.SetParent(root.transform, false);
        nozzle.transform.localPosition = new Vector3(0.3f, 1.0f, 0.95f);
        nozzle.transform.localRotation = Quaternion.identity;

        AssignReferences(absorber, nozzle.transform);

        EditorSceneManager.MarkSceneDirty(root.scene);
        Selection.activeGameObject = root;
        Debug.Log("S.U.C.K.-3000 prop built and Nozzle assigned. Save the scene with Ctrl + S.");
    }

    private static void AssignReferences(VacuumAbsorber absorber, Transform nozzle)
    {
        SerializedObject serialized = new SerializedObject(absorber);

        SerializedProperty nozzleProperty = serialized.FindProperty("nozzle");
        if (nozzleProperty != null)
        {
            nozzleProperty.objectReferenceValue = nozzle;
        }

        SerializedProperty inventoryProperty = serialized.FindProperty("inventory");
        if (inventoryProperty != null && inventoryProperty.objectReferenceValue == null)
        {
            BackpackInventory inventory = absorber.GetComponent<BackpackInventory>();
            if (inventory != null)
            {
                inventoryProperty.objectReferenceValue = inventory;
            }
        }

        serialized.ApplyModifiedProperties();
    }

    private static GameObject CreatePart(
        Transform parent, string partName, PrimitiveType type,
        Vector3 localPosition, Quaternion localRotation, Vector3 localScale, Material material)
    {
        GameObject part = GameObject.CreatePrimitive(type);
        part.name = partName;

        // Decorative only: no collider, so it never pushes the player or blocks anything.
        Object.DestroyImmediate(part.GetComponent<Collider>());

        part.transform.SetParent(parent, false);
        part.transform.localPosition = localPosition;
        part.transform.localRotation = localRotation;
        part.transform.localScale = localScale;
        part.GetComponent<MeshRenderer>().sharedMaterial = material;
        return part;
    }

    private static void CreateTube(
        Transform parent, string tubeName, Vector3 from, Vector3 to, float radius, Material material)
    {
        Vector3 direction = to - from;
        float length = direction.magnitude;

        // A Unity cylinder is 2 units tall and 1 unit wide, so the scale is half the length.
        CreatePart(parent, tubeName, PrimitiveType.Cylinder,
            (from + to) / 2f,
            Quaternion.FromToRotation(Vector3.up, direction.normalized),
            new Vector3(radius * 2f, length / 2f, radius * 2f),
            material);
    }

    private static Material GetMaterial(string materialName, Color color, float metallic, float smoothness, bool emissive)
    {
        if (!AssetDatabase.IsValidFolder(MaterialFolder))
        {
            AssetDatabase.CreateFolder("Assets", "GameMaterials");
        }

        string path = MaterialFolder + "/" + materialName + ".mat";
        Material material = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (material != null) return material;

        Shader shader = Shader.Find("Universal Render Pipeline/Lit");
        if (shader == null)
        {
            shader = Shader.Find("Standard");
        }

        material = new Material(shader);
        if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
        if (material.HasProperty("_Color")) material.SetColor("_Color", color);
        if (material.HasProperty("_Metallic")) material.SetFloat("_Metallic", metallic);
        if (material.HasProperty("_Smoothness")) material.SetFloat("_Smoothness", smoothness);
        if (material.HasProperty("_Glossiness")) material.SetFloat("_Glossiness", smoothness);

        if (emissive)
        {
            material.EnableKeyword("_EMISSION");
            material.SetColor("_EmissionColor", color * 3f);
        }

        AssetDatabase.CreateAsset(material, path);
        return material;
    }
}
#endif
